'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var startsWith = require( '@stdlib/string/base/starts-with' );
var containsArray = require( '@stdlib/array/base/assert/contains' );
var FUNCTION_DATABASE = require( '@stdlib/math/special/data/unary_function_database.json' );


// MAIN //

/**
* Returns the package dependencies environment variable.
*
* @private
* @param {string} pkg - function name (e.g., 'acosd')
* @returns {string} environment variable string
*
* @example
* var deps = pkgDepsEnvVar( 'acosd' );
* // returns 'PKG_DEPS=\'"@stdlib/math/base/special/acosdf",\n        "@stdlib/math/base/special/acosd"\''
*/
function pkgDepsEnvVar( pkg ) {
	var scalarKernels;
	var kernelPaths;
	var depsString;
	var kernelPath;
	var funcData;
	var keys;
	var i;

	funcData = FUNCTION_DATABASE[ pkg ];
	if ( !funcData || !funcData.scalar_kernels ) {
		return 'PKG_DEPS=\'\'';
	}

	// Using the scalar kernels to compute the dependencies:
	scalarKernels = funcData.scalar_kernels;
	keys = objectKeys( scalarKernels );
	kernelPaths = [];

	for ( i = 0; i < keys.length; i++ ) {
		kernelPath = scalarKernels[ keys[ i ] ];
		if ( startsWith( kernelPath, '/' ) ) {
			kernelPath = '@stdlib' + kernelPath;
		}

		// Avoiding duplicate dependencies:
		if ( !containsArray( kernelPaths, '"' + kernelPath + '"' ) ) {
			kernelPaths.push( '"' + kernelPath + '"' );
		}
	}

	depsString = kernelPaths.join( ',\n        ' );
	return 'PKG_DEPS=\'' + depsString + '\'';
}


// EXPORTS //

module.exports = pkgDepsEnvVar;
